package oltsecrets

import (
	"crypto/ed25519"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// vectors.json is the file of ADR-0045 generated by an independent implementation (Python cryptography). Go must reproduce the sealing byte for byte, open the blobs and
// verify the Ed25519 signature.
type vectorFile struct {
	Edge struct {
		PrivateScalarHex string `json:"private_scalar_hex"`
		PublicPoint      string `json:"public_point_b64url"`
		KeyID            string `json:"key_id"`
		Fingerprint      string `json:"fingerprint"`
	} `json:"edge"`
	Ephemeral struct {
		PrivateScalarHex string `json:"private_scalar_hex"`
		NonceHex         string `json:"nonce_hex"`
	} `json:"ephemeral"`
	Cases []struct {
		Kind          string `json:"kind"`
		AAD           string `json:"aad"`
		PlaintextJSON string `json:"plaintext_json"`
		SealedB64URL  string `json:"sealed_b64url"`
		BlobLen       int    `json:"blob_len"`
	} `json:"cases"`
	Sig struct {
		SeedHex   string `json:"ed25519_seed_hex"`
		PublicKey string `json:"public_key_b64url"`
		CaseIndex int    `json:"case_index"`
		Message   string `json:"message_utf8"`
		Signature string `json:"signature_b64url"`
	} `json:"delivery_signature"`
}

func loadVectors(t *testing.T) *vectorFile {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "..", "..", "..", "docs", "addenda", "olt-secrets", "vectors.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v vectorFile
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return &v
}

func TestVectorsKeyIdentity(t *testing.T) {
	v := loadVectors(t)
	scalar, _ := hex.DecodeString(v.Edge.PrivateScalarHex)
	k, err := KeyFromScalar(scalar)
	if err != nil {
		t.Fatal(err)
	}
	if k.PublicB64() != v.Edge.PublicPoint || k.KeyID() != v.Edge.KeyID || k.Fingerprint() != v.Edge.Fingerprint {
		t.Fatalf("public=%s key_id=%s fp=%s", k.PublicB64(), k.KeyID(), k.Fingerprint())
	}
}

func TestVectorsSealingIsReproducedByteForByte(t *testing.T) {
	v := loadVectors(t)
	point, _ := b64.DecodeString(v.Edge.PublicPoint)
	eph := mustEphemeral(t, v.Ephemeral.PrivateScalarHex)
	nonce, _ := hex.DecodeString(v.Ephemeral.NonceHex)
	for _, c := range v.Cases {
		got, err := SealWith(point, eph, nonce, []byte(c.AAD), []byte(c.PlaintextJSON))
		if err != nil {
			t.Fatal(err)
		}
		if b64.EncodeToString(got) != c.SealedB64URL || len(got) != c.BlobLen {
			t.Fatalf("%s: sealed differs from the vector (len %d, want %d)", c.Kind, len(got), c.BlobLen)
		}
	}
}

func TestVectorsBlobsOpenAndTheAADIsBound(t *testing.T) {
	v := loadVectors(t)
	scalar, _ := hex.DecodeString(v.Edge.PrivateScalarHex)
	k, _ := KeyFromScalar(scalar)
	for _, c := range v.Cases {
		blob, err := b64.DecodeString(c.SealedB64URL)
		if err != nil {
			t.Fatal(err)
		}
		pt, err := k.Open(blob, []byte(c.AAD))
		if err != nil || string(pt) != c.PlaintextJSON {
			t.Fatalf("%s: open failed: %v", c.Kind, err)
		}
		if _, err := k.Open(blob, []byte(c.AAD+"x")); err == nil {
			t.Fatalf("%s: a different AAD must not open", c.Kind)
		}
	}
}

func TestVectorsDeliverySignatureVerifies(t *testing.T) {
	v := loadVectors(t)
	seed, _ := hex.DecodeString(v.Sig.SeedHex)
	priv := ed25519.NewKeyFromSeed(seed)
	pubWire, _ := b64.DecodeString(v.Sig.PublicKey)
	if string(pubWire) != string(priv.Public().(ed25519.PublicKey)) {
		t.Fatal("public key of the vector does not match its seed")
	}
	c := v.Cases[v.Sig.CaseIndex]
	blob, _ := b64.DecodeString(c.SealedB64URL)
	msg := SignedMessage([]byte(c.AAD), blob)
	if string(msg) != v.Sig.Message {
		t.Fatalf("signed message differs:\n%q\n%q", msg, v.Sig.Message)
	}
	sig, err := b64.DecodeString(v.Sig.Signature)
	if err != nil || !ed25519.Verify(pubWire, msg, sig) {
		t.Fatal("the vector signature does not verify")
	}
	// and the one this code makes is the same (Ed25519 is deterministic)
	if b64.EncodeToString(ed25519.Sign(priv, msg)) != v.Sig.Signature {
		t.Fatal("Go signature differs from the vector")
	}
}

func TestVectorAADIsBuiltFromTheFields(t *testing.T) {
	v := loadVectors(t)
	got := AAD("11111111-1111-4111-8111-111111111111", "22222222-2222-4222-8222-222222222222", "OLT-CENTRO-01", "ssh_login", "33333333-3333-4333-8333-333333333333", "9bdcc5ffbbdf3efc", 1893456000)
	if string(got) != v.Cases[0].AAD {
		t.Fatalf("%q", got)
	}
}

// The whole Process path, on the vectors' own data: the delivery of case 0, signed with the vector's signature, applied to a credentials file.
func TestVectorDeliveryIsAppliedEndToEnd(t *testing.T) {
	v := loadVectors(t)
	e := newEnv(t)
	c := v.Cases[0]
	blob, _ := b64.DecodeString(c.SealedB64URL)
	d := e.sign(spec{id: tDelivery, olt: tOLT, kind: "ssh_login", keyID: v.Edge.KeyID, exp: 1893456000}, blob)
	if d.Signature != v.Sig.Signature {
		t.Fatal("the signature built by the test fixture is not the vector's")
	}
	e.wantApplied(d)
	got := e.readFile(e.credPath)
	if !strings.Contains(got, `"username":"admin-olt"`) || !strings.Contains(got, `"v":1`) {
		t.Fatalf("file: %s", got)
	}
}

func TestOpenRejectsMalformedBlobs(t *testing.T) {
	e := newEnv(t)
	aad := []byte("x")
	good, _ := Seal(e.key.PublicPoint(), aad, []byte("{}"))
	cases := map[string][]byte{
		"empty":       nil,
		"short":       good[:40],
		"version":     append([]byte{0x02}, good[1:]...),
		"not-a-point": append(append([]byte{0x01}, make([]byte, 65)...), good[66:]...),
		"oversize":    append(append([]byte{}, good...), make([]byte, MaxBlobBytes)...),
	}
	for name, blob := range cases {
		if _, err := e.key.Open(blob, aad); err == nil {
			t.Errorf("%s: must not open", name)
		}
	}
	if _, err := e.key.Open(good, aad); err != nil {
		t.Fatal(err)
	}
}

func TestKeyFileIsGeneratedOnceAndNeverRegeneratedOverABrokenOne(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "keys") // does not exist: created 0700
	path := filepath.Join(dir, "seal.key")
	k1, created, err := LoadOrCreateKey(path)
	if err != nil || !created {
		t.Fatalf("created=%v err=%v", created, err)
	}
	if fi, _ := os.Stat(dir); fi.Mode().Perm() != 0o700 {
		t.Fatalf("dir mode %v", fi.Mode().Perm())
	}
	if fi, _ := os.Stat(path); fi.Mode().Perm() != 0o600 {
		t.Fatalf("file mode %v", fi.Mode().Perm())
	}
	k2, created, err := LoadOrCreateKey(path)
	if err != nil || created || k2.KeyID() != k1.KeyID() {
		t.Fatalf("the same key must come back: created=%v err=%v", created, err)
	}
	// a corrupt key file is an error, NEVER a new key
	if err := os.WriteFile(path, []byte("garbage"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, created, err := LoadOrCreateKey(path); err == nil || created {
		t.Fatalf("corrupt key file must fail closed: created=%v err=%v", created, err)
	}
	// loose permissions are refused
	if err := os.WriteFile(path, []byte("{}"), 0o644); err != nil {
		t.Fatal(err)
	}
	_ = os.Chmod(path, 0o644)
	if _, err := LoadKey(path); err == nil {
		t.Fatal("a 0644 key file must be refused")
	}
	// loose directory is refused
	_ = os.Chmod(path, 0o600)
	if err := os.Chmod(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if _, err := LoadKey(path); err == nil {
		t.Fatal("a 0755 key directory must be refused")
	}
}

func TestKeyErrorsAndStringsNeverCarryTheScalar(t *testing.T) {
	dir := privDir(t)
	path := filepath.Join(dir, "seal.key")
	k, _, err := LoadOrCreateKey(path)
	if err != nil {
		t.Fatal(err)
	}
	raw, _ := os.ReadFile(path)
	var kf keyFile
	_ = json.Unmarshal(raw, &kf)
	// break the file in a way that keeps the scalar text inside it
	_ = os.WriteFile(path, []byte(`{"v":2,"alg":"ECDH-P256","private":"`+kf.Private+`"}`), 0o600)
	_, err = LoadKey(path)
	if err == nil || strings.Contains(err.Error(), kf.Private) {
		t.Fatalf("error must exist and not carry the key: %v", err)
	}
	if strings.Contains(k.PublicB64(), kf.Private) || strings.Contains(k.Fingerprint(), kf.Private) {
		t.Fatal("public strings carry the private scalar")
	}
}
